import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"第四册：流利英语 · 综合复习与自测 · 第12–22课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第四册：流利英语 · 综合复习与自测 · 第12–22课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-4/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第1–11课","link":"/life/english/new-concept/book-4/review-part-01"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第23–33课","link":"/life/english/new-concept/book-4/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 综合复习与自测 · 第1–11课","link":"/life/english/new-concept/book-4/review-part-01"},"next":{"text":"第四册：流利英语 · 综合复习与自测 · 第23–33课","link":"/life/english/new-concept/book-4/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-4/review-part-02.md","filePath":"life/english/new-concept/book-4/review-part-02.md"}'),n={name:"life/english/new-concept/book-4/review-part-02.md"};function r(l,e,i,h,c,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-综合复习与自测-·-第12–22课" tabindex="-1">第四册：流利英语 · 综合复习与自测 · 第12–22课 <a class="header-anchor" href="#第四册-流利英语-·-综合复习与自测-·-第12–22课" aria-label="Permalink to &quot;第四册：流利英语 · 综合复习与自测 · 第12–22课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-12-·-unless-与条件从句" tabindex="-1">Lesson 12 · unless 与条件从句 <a class="header-anchor" href="#lesson-12-·-unless-与条件从句" aria-label="Permalink to &quot;Lesson 12 · unless 与条件从句 {#lesson-12-·-unless-与条件从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In this exercise, the request will remain pending unless the customer signs the form.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>将 unless the customer signs 改为 if 结构。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> if the customer does not sign</p><p><strong>解析：</strong> unless 在本句等于 if not。</p></details><p><strong>表达迁移：</strong> 为虚构服务台写三句申请说明：所需文件、缺失时的结果、咨询方式。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Please attach a copy of your identification. The request will remain pending unless the copy is included. Contact the service desk if you need help with the form.</p><p>申请条件和未满足的后果分别表达，第三句提供行动入口。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">回看本课</a></p><h2 id="lesson-13-·-目的不定式与-so-that" tabindex="-1">Lesson 13 · 目的不定式与 so that <a class="header-anchor" href="#lesson-13-·-目的不定式与-so-that" aria-label="Permalink to &quot;Lesson 13 · 目的不定式与 so that {#lesson-13-·-目的不定式与-so-that}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The team collected rock samples so that specialists could compare the layers.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>示例中收集者和比较者的称呼分别是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the team 和 specialists</p><p><strong>解析：</strong> 两个分句的主语分别指明角色。</p></details><p><strong>表达迁移：</strong> 用三句说明一次虚构勘测：采集什么、为何分析、下一步取决于什么。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We collected samples to compare the rock layers. The results may reveal differences in their structure. Further testing will be needed before any conclusion is drawn.</p><p>目的、可能发现、结论限制依次展开，没有把勘测等同于资源发现。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">回看本课</a></p><h2 id="lesson-14-·-第二条件句与假设距离" tabindex="-1">Lesson 14 · 第二条件句与假设距离 <a class="header-anchor" href="#lesson-14-·-第二条件句与假设距离" aria-label="Permalink to &quot;Lesson 14 · 第二条件句与假设距离 {#lesson-14-·-第二条件句与假设距离}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If we changed the starting value slightly, the two simulations might diverge over time.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>示例是在报告已经改变了数值吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> if changed 与 might 构成假设情境。</p></details><p><strong>表达迁移：</strong> 为两个模拟结果写三句说明，提出一个变量变化假设并指出预测限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The two curves begin close together. If we altered one starting value, they might separate later. This example illustrates sensitivity, but it does not predict a particular storm.</p><p>把图形描述、假设实验和外推边界分别表达，避免把隐喻当成事件证明。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">回看本课</a></p><h2 id="lesson-15-·-whether-引导名词性从句" tabindex="-1">Lesson 15 · whether 引导名词性从句 <a class="header-anchor" href="#lesson-15-·-whether-引导名词性从句" aria-label="Permalink to &quot;Lesson 15 · whether 引导名词性从句 {#lesson-15-·-whether-引导名词性从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The team must decide whether the preliminary data can be shared with partners.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>填空：They discussed ___ to publish the design.（whether / if）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> whether</p><p><strong>解析：</strong> whether 可以直接接不定式，if 通常不能。</p></details><p><strong>表达迁移：</strong> 写三句团队讨论记录：待决策事项、共享的一个好处、需要核查的一个条件。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We need to decide whether to share the test data. Collaboration could help another team check our results. Before release, we should identify any confidential information.</p><p>whether to 提出选择，could 说明可能收益，before 限定发布前的检查。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">回看本课</a></p><h2 id="lesson-16-·-so-that-与-such-that-的结果表达" tabindex="-1">Lesson 16 · so…that 与 such…that 的结果表达 <a class="header-anchor" href="#lesson-16-·-so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;Lesson 16 · so…that 与 such…that 的结果表达 {#lesson-16-·-so-that-与-such-that-的结果表达}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The crossing was so far away that several residents asked for a nearer one.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>填空：It was ___ a narrow pavement that two people could not pass.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> such</p><p><strong>解析：</strong> 后面是 a narrow pavement 名词短语。</p></details><p><strong>表达迁移：</strong> 用三句描述一个街区步行问题，包含程度结果结构和一条改善建议。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The bus stop is so far from the library that some visitors drive instead. A nearer stop could make the library easier to reach. The council should also ask residents about their routes.</p><p>先给具体空间问题，再提出可能改善和信息收集，不把单一观察泛化为所有城市。</p></details><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">回看本课</a></p><h2 id="lesson-17-·-cause、lead-to-与-be-associated-with" tabindex="-1">Lesson 17 · cause、lead to 与 be associated with <a class="header-anchor" href="#lesson-17-·-cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;Lesson 17 · cause、lead to 与 be associated with {#lesson-17-·-cause、lead-to-与-be-associated-with}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>示例是否已经证明更潮湿的春季导致兔子减少？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> be associated with 表关联，还需要排除其他解释。</p></details><p><strong>表达迁移：</strong> 为虚构兔子数量调查写三句摘要：一项关联、另一种解释、后续观察需要。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A wetter spring was associated with fewer rabbits near the field. Changes in food supply may also explain the difference. A better survey would compare several sites over more than one season.</p><p>用关联、替代解释和跨地点观察构成谨慎摘要，不据历史疾病故事提供干预步骤。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">回看本课</a></p><h2 id="lesson-18-·-感官动词的主动与被动转换" tabindex="-1">Lesson 18 · 感官动词的主动与被动转换 <a class="header-anchor" href="#lesson-18-·-感官动词的主动与被动转换" aria-label="Permalink to &quot;Lesson 18 · 感官动词的主动与被动转换 {#lesson-18-·-感官动词的主动与被动转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The animal was seen to surface beside the boat twice.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>把 We saw the animal turn. 改成被动句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The animal was seen to turn.</p><p><strong>解析：</strong> 被动结构中的不定式恢复 to。</p></details><p><strong>表达迁移：</strong> 写三句海边观察笔记：一次所见、一个未知问题、一次进一步观察计划。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A small animal was seen to surface near the harbour. We could not identify its species from that distance. Next time, we will record its shape and movement more carefully.</p><p>描述行为而不编造意图，并把物种识别的不确定性写出来。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">回看本课</a></p><h2 id="lesson-19-·-同位语从句与定语从句" tabindex="-1">Lesson 19 · 同位语从句与定语从句 <a class="header-anchor" href="#lesson-19-·-同位语从句与定语从句" aria-label="Permalink to &quot;Lesson 19 · 同位语从句与定语从句 {#lesson-19-·-同位语从句与定语从句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The belief that every dream has one fixed meaning is difficult to justify.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>示例中的 that 从句说明 belief 的内容还是修饰提出它的人？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 说明 belief 的内容。</p><p><strong>解析：</strong> 从句本身结构完整。</p></details><p><strong>表达迁移：</strong> 写三句评价一个梦的解释：陈述回忆、提出可能联系、保留其他解释。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I remembered a dream about a crowded station. It may have reflected my worries about an upcoming trip. That interpretation is possible, but it is not the only one.</p><p>回忆与解释分句处理，may 和 not the only one 避免把主观推测当成唯一答案。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">回看本课</a></p><h2 id="lesson-20-·-过去分词作后置定语" tabindex="-1">Lesson 20 · 过去分词作后置定语 <a class="header-anchor" href="#lesson-20-·-过去分词作后置定语" aria-label="Permalink to &quot;Lesson 20 · 过去分词作后置定语 {#lesson-20-·-过去分词作后置定语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The samples collected on Tuesday were analysed separately.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>展开 samples collected on Tuesday 中的分词定语。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> samples that were collected on Tuesday</p><p><strong>解析：</strong> 过去分词定语对应被动关系从句。</p></details><p><strong>表达迁移：</strong> 用三句写实验样本管理说明，包含采集、分组和结论范围。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The samples collected at different sites were kept separate. Each group was given a clear label. Results from one group cannot automatically be applied to another.</p><p>用分词定语说明来源，用末句避免跨组过度概括；不涉及危险操作或医疗处置。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">回看本课</a></p><h2 id="lesson-21-·-it-is-was-that-强调句" tabindex="-1">Lesson 21 · It is/was…that 强调句 <a class="header-anchor" href="#lesson-21-·-it-is-was-that-强调句" aria-label="Permalink to &quot;Lesson 21 · It is/was…that 强调句 {#lesson-21-·-it-is-was-that-强调句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It was the actor’s silence that made the final scene so tense.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>还原示例为普通陈述句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The actor’s silence made the final scene so tense.</p><p><strong>解析：</strong> 去掉强调框架后主干完整。</p></details><p><strong>表达迁移：</strong> 用三句评论一段自选无声电影片段，说明哪种表演手段影响了你。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>It was the long pause that caught my attention. The actor looked towards the empty doorway without moving. This small gesture created more tension than a dramatic speech would have done.</p><p>强调句提出观察焦点，具体动作提供依据，比较句说明效果。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">回看本课</a></p><h2 id="lesson-22-·-what-从句作主语与表语" tabindex="-1">Lesson 22 · what 从句作主语与表语 <a class="header-anchor" href="#lesson-22-·-what-从句作主语与表语" aria-label="Permalink to &quot;Lesson 22 · what 从句作主语与表语 {#lesson-22-·-what-从句作主语与表语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What matters is whether the new tool solves a real problem.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>示例中主句的系动词是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 前后两个从句由 is 连接。</p></details><p><strong>表达迁移：</strong> 用三句评价一款虚构学习工具，给出一个进步标准和一个验证方法。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What matters is whether students understand more. Faster completion alone does not prove deeper learning. We could compare how well students explain a new problem after using the tool.</p><p>先定标准，再排除替代指标，最后提出能对应标准的验证方式。</p></details><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">回看本课</a></p>',92)])])}const u=s(n,[["render",r]]);export{m as __pageData,u as default};
